<script>
(function(){
 const token=document.querySelector('#program-edit-form input[name="_token"]')?.value||document.querySelector('input[name="_token"]')?.value;
 function filterDepartments(select,faculty,selected){[...select.options].forEach((o,i)=>{if(i) o.hidden=!!faculty&&o.dataset.faculty!==faculty;});if(selected)select.value=selected;if(select.selectedOptions[0]?.hidden)select.value='';}
 document.querySelectorAll('.js-faculty').forEach(f=>f.addEventListener('change',()=>{const d=f.closest('form')?.querySelector('.js-department');if(d)filterDepartments(d,f.value,'');}));
 const ff=document.getElementById('program-faculty'),fd=document.getElementById('program-department');ff?.addEventListener('change',()=>filterDepartments(fd,ff.value,''));if(ff&&fd)filterDepartments(fd,ff.value,{{ json_encode($selectedDepartment) }});
 function decodeProgram(value){const bytes=Uint8Array.from(atob(value),c=>c.charCodeAt(0));return JSON.parse(new TextDecoder().decode(bytes));}
 document.querySelectorAll('.js-edit-program').forEach(b=>b.addEventListener('click',()=>{const p=decodeProgram(b.dataset.program),f=document.getElementById('program-edit-form');f.dataset.originalDuration=String(p.duration||'');f.dataset.syncComplete='0';[['edit-id','id'],['edit-code','code'],['edit-no','no'],['edit-title','title'],['edit-duration','duration'],['edit-de','de'],['edit-award','award'],['edit-award-title','award_title'],['edit-courses','courses']].forEach(([id,key])=>document.getElementById(id).value=p[key]??'');document.getElementById('edit-faculty').value=p.faculty||'';filterDepartments(document.getElementById('edit-department'),p.faculty||'',p.department||'');}));
 document.querySelectorAll('.js-delete-program').forEach(b=>b.addEventListener('click',()=>{document.getElementById('delete-program-id').value=b.dataset.id;document.getElementById('delete-program-title').textContent=b.dataset.title||'this programme';}));
 async function syncDuration(form,code,id,duration){const panel=document.getElementById('duration-progress-panel'),bar=document.getElementById('duration-progress-bar'),count=document.getElementById('duration-progress-count'),percent=document.getElementById('duration-progress-percent'),msg=document.getElementById('duration-progress-message');panel.classList.add('show');let lastId=0,processed=0,total=0;try{do{const r=await fetch(@json(route('program.sync-duration')),{method:'POST',headers:{'Content-Type':'application/json','Accept':'application/json','X-CSRF-TOKEN':token},body:JSON.stringify({id,code,duration,last_id:lastId,processed,batch:500})}),d=await r.json();if(!r.ok)throw new Error(d.message||'Duration synchronisation failed.');total=Number(d.total||0);processed=Number(d.processed||processed);lastId=Number(d.last_id||lastId);const v=total?Math.min(100,Math.round(processed/total*100)):100;bar.style.width=v+'%';percent.textContent=v+'%';count.textContent=processed.toLocaleString()+' of '+total.toLocaleString()+' student records';msg.textContent=total?'Applying the new duration to every linked student…':'No students are linked to this programme.';if(d.done)break;}while(true);form.dataset.syncComplete='1';msg.textContent='Student records synchronised. Saving programme details…';HTMLFormElement.prototype.submit.call(form);}catch(e){panel.classList.remove('show');alert(e.message||'Duration synchronisation failed. No programme details were saved.');}}
 document.getElementById('program-edit-form')?.addEventListener('submit',function(e){if(this.dataset.syncComplete==='1')return;const old=String(this.dataset.originalDuration||''),now=String(document.getElementById('edit-duration').value||'');if(old===now)return;e.preventDefault();const btn=document.getElementById('edit-save-btn');btn.disabled=true;syncDuration(this,document.getElementById('edit-code').value,document.getElementById('edit-id').value,Number(now)).finally(()=>btn.disabled=false);});
})();
</script>
@endpush
